SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY "centerId" DESC) AS RNUM, TB.* FROM ( SELECT A.CENTER_ID AS "centerId", A.CENTER_NM AS "centerNm", A.CENTER_STARTTIME AS "centerStartTime", A.CENTER_ENDTIME AS "centerEndTime", A.CENTER_USEYN AS "centerUseYn", A.CENTER_GUBUN AS "centerGubun", B.CODE_NM AS "codeNm", A.CENTER_REGDATE AS "centerRegdate" FROM TB_CENTERINFO A INNER JOIN COMTCCMMNDETAILCODE B ON A.CENTER_GUBUN = B.CODE WHERE 1=1
AND CENTER_ID LIKE CONCAT('%', #{searchKeyword}, '%')
AND CENTER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND CENTER_GUBUN = 'BRANCH01'
AND CENTER_GUBUN = 'BRANCH01'
) TB ) TA WHERE RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

